// The demo carries its own JavaScript port of the codec. This runs that port
// against a fixture generated by the Python reference, so the two cannot drift.
// Regenerate the fixture with tools/gridcode/build_fixture.py after any change.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, '..', '..', 'demos', 'word-grid.html'), 'utf8');
const fixture = JSON.parse(readFileSync(join(here, 'fixture.json'), 'utf8'));

// Take the word list and everything from the SHA-256 block down to the map code.
const words = html.match(/const WORDS = (\[[^\n]*\]);/)[1];
const start = html.indexOf('const INDEX = new Map');
const end = html.indexOf('// --- map ---');
const src = `const WORDS = ${words};\n${html.slice(start, end)}\nexport { encode, decode };`;
const mod = await import('data:text/javascript,' + encodeURIComponent(src));

let bad = 0;
for (const c of fixture) {
  for (const [bits, key] of [[0, 'a0'], [8, 'a8']]) {
    const got = mod.encode(c.lat, c.lng, bits);
    if (got.join('.') !== c[key].join('.')) {
      bad++;
      console.error(`  MISMATCH ${c.lat},${c.lng} @${bits}: js ${got.join('.')} vs py ${c[key].join('.')}`);
    }
    // and the address must resolve back to where it came from
    const [lat, lng] = mod.decode(c[key], c.lat, c.lng, bits);
    if (Math.abs(lat - c.lat) > 0.001 || Math.abs(lng - c.lng) > 0.001) {
      bad++;
      console.error(`  ROUND TRIP ${c.lat},${c.lng} @${bits} -> ${lat},${lng}`);
    }
  }
}
console.log(`demo codec vs python reference: ${fixture.length} points x 2 settings`);
if (bad) { console.error(`FAIL: ${bad} problem(s)`); process.exit(1); }
console.log('OK: demo JavaScript agrees with the Python reference, and round trips');
